package ua.budivelnyk.ua;
import android.app.Activity;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import com.googlecode.tesseract.android.TessBaseAPI;import android.content.Intent;import android.content.ClipData;import android.net.Uri;import android.os.Bundle;import android.graphics.pdf.PdfRenderer;import android.os.ParcelFileDescriptor;import android.os.Environment;import android.util.Base64;import android.webkit.JavascriptInterface;import android.webkit.ValueCallback;import android.webkit.WebChromeClient;import android.webkit.WebSettings;import android.webkit.WebView;import android.webkit.WebViewClient;import org.json.JSONArray;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Arrays;import android.content.SharedPreferences;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import java.security.KeyStore;import javax.crypto.Cipher;import javax.crypto.KeyGenerator;import javax.crypto.SecretKey;import javax.crypto.spec.GCMParameterSpec;
public class MainActivity extends Activity{private static final int PICK=1401,SAVE=1402;private ValueCallback<Uri[]> callback;private byte[] pendingExport;private String pendingExportName;private WebView activeWebView;private File folder(String c){File root=getExternalFilesDir(Environment.DIRECTORY_PICTURES);if(root==null)root=getFilesDir();File d=new File(root,"drawings".equals(c)?"Креслення":"Фото_виробів");if(!d.exists())d.mkdirs();return d;}public class AndroidStorage{@JavascriptInterface public String recognizeImage(String data,String language){TessBaseAPI api=null;try{int comma=data.indexOf(',');byte[] raw=Base64.decode(comma>=0?data.substring(comma+1):data,Base64.DEFAULT);Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length);if(bitmap==null)return "Помилка: не вдалося прочитати зображення";File root=new File(getFilesDir(),"tesseract");File td=new File(root,"tessdata");if(!td.exists())td.mkdirs();String[] langs={"ukr","rus","eng"};for(String lang:langs){File model=new File(td,lang+".traineddata");if(!model.exists()){try(InputStream in=getAssets().open("tessdata/"+lang+".traineddata");FileOutputStream out=new FileOutputStream(model)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}}}String selected=("ukr+rus+eng").equals(language)?"ukr+rus+eng":"ukr+rus+eng";api=new TessBaseAPI();if(!api.init(root.getAbsolutePath(),selected))return "OCR не запустився: перевірте мовні файли ukr.traineddata, rus.traineddata та eng.traineddata в assets/tessdata.";api.setPageSegMode(TessBaseAPI.PageSegMode.AUTO);api.setImage(bitmap);String result=api.getUTF8Text();return result==null?"":result;}catch(Exception e){return "OCR недоступний: "+e.getMessage();}finally{if(api!=null)api.end();}}
@JavascriptInterface public String recognizePdf(String data,String language){
 TessBaseAPI api=null;File pdf=null;ParcelFileDescriptor pfd=null;PdfRenderer renderer=null;
 try{
  int comma=data.indexOf(',');byte[] raw=Base64.decode(comma>=0?data.substring(comma+1):data,Base64.DEFAULT);
  if(raw.length==0||raw.length>20*1024*1024)return "PDF має бути не порожнім і не більшим за 20 МБ.";
  File root=new File(getFilesDir(),"tesseract");File td=new File(root,"tessdata");if(!td.exists())td.mkdirs();
  String[] langs={"ukr","rus","eng"};for(String lang:langs){File model=new File(td,lang+".traineddata");if(!model.exists()){try(InputStream in=getAssets().open("tessdata/"+lang+".traineddata");FileOutputStream out=new FileOutputStream(model)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}}}
  String selected="ukr+rus+eng";api=new TessBaseAPI();if(!api.init(root.getAbsolutePath(),selected))return "OCR не запустився: перевірте мовні файли.";
  api.setPageSegMode(TessBaseAPI.PageSegMode.AUTO);
  pdf=File.createTempFile("butdetal_ocr_",".pdf",getCacheDir());try(FileOutputStream out=new FileOutputStream(pdf)){out.write(raw);}
  pfd=ParcelFileDescriptor.open(pdf,ParcelFileDescriptor.MODE_READ_ONLY);renderer=new PdfRenderer(pfd);
  int pages=renderer.getPageCount();if(pages>30)return "PDF має "+pages+" сторінок. Максимум для одного запуску — 30.";
  StringBuilder result=new StringBuilder();
  for(int i=0;i<pages;i++){
   PdfRenderer.Page page=renderer.openPage(i);
   try{
    int w=Math.max(1,page.getWidth()*2),h=Math.max(1,page.getHeight()*2);
    double scale=Math.min(1.0,Math.min(3000.0/w,4000.0/h));w=Math.max(1,(int)(w*scale));h=Math.max(1,(int)(h*scale));
    Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);
    try{page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);api.setImage(bitmap);String text=api.getUTF8Text();result.append("\n\n===== СТОРІНКА ").append(i+1).append(" =====\n");result.append(text==null?"":text);result.append("\n");}
    finally{bitmap.recycle();}
   }finally{page.close();}
  }
  return result.length()==0?"Текст не знайдено.":result.toString();
 }catch(Exception e){return "Помилка OCR PDF: "+e.getMessage();}
 finally{if(renderer!=null)renderer.close();if(pfd!=null)try{pfd.close();}catch(Exception ignored){}if(pdf!=null)pdf.delete();if(api!=null)api.end();}
}
private SecretKey credentialKey()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);String alias="BUTDETAL_CREDENTIAL_KEY";if(ks.containsAlias(alias))return (SecretKey)ks.getKey(alias,null);KeyGenerator kg=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());return kg.generateKey();}@JavascriptInterface public String saveCredential(String email,String password){try{JSONObject o=new JSONObject();o.put("email",email);o.put("password",password);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,credentialKey());byte[] encrypted=c.doFinal(o.toString().getBytes(StandardCharsets.UTF_8));SharedPreferences p=getSharedPreferences("butdetal_secure_v1",MODE_PRIVATE);p.edit().putString("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).putString("data",Base64.encodeToString(encrypted,Base64.NO_WRAP)).apply();return "OK";}catch(Exception e){return "Не вдалося безпечно зберегти пароль: "+e.getMessage();}}@JavascriptInterface public String getCredential(){try{SharedPreferences p=getSharedPreferences("butdetal_secure_v1",MODE_PRIVATE);String iv=p.getString("iv",null),data=p.getString("data",null);if(iv==null||data==null)return "";Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,credentialKey(),new GCMParameterSpec(128,Base64.decode(iv,Base64.DEFAULT)));return new String(c.doFinal(Base64.decode(data,Base64.DEFAULT)),StandardCharsets.UTF_8);}catch(Exception e){return "";}}@JavascriptInterface public void clearCredential(){getSharedPreferences("butdetal_secure_v1",MODE_PRIVATE).edit().clear().apply();try{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias("BUTDETAL_CREDENTIAL_KEY"))ks.deleteEntry("BUTDETAL_CREDENTIAL_KEY");}catch(Exception ignored){}}@JavascriptInterface public String saveDocument(String name,String mime,String base64){try{pendingExport=Base64.decode(base64,Base64.DEFAULT);pendingExportName=name;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,SAVE);return "OK";}catch(Exception e){pendingExport=null;return "Помилка відкриття збереження: "+e.getMessage();}}@JavascriptInterface public String savePdf(String name,String base64,String title,String notes){try{byte[] data=Base64.decode(base64,Base64.DEFAULT);if(data.length==0||data.length>20*1024*1024)return "PDF має бути до 20 МБ.";if(data.length<5||data[0]!='%'||data[1]!='P'||data[2]!='D'||data[3]!='F')return "Файл не схожий на PDF.";File d=new File(folder("drawings"),"PDF");if(!d.exists()&&!d.mkdirs())return "Не вдалося створити папку PDF.";String safe=name.replaceAll("[^a-zA-Z0-9а-яА-ЯіІїЇєЄ._-]","_");if(!safe.toLowerCase().endsWith(".pdf"))safe+=".pdf";String base=safe;int k=1;while(new File(d,safe).exists()){int dot=base.toLowerCase().lastIndexOf(".pdf");safe=base.substring(0,dot)+"_"+(k++)+".pdf";}File f=new File(d,safe);try(FileOutputStream o=new FileOutputStream(f)){o.write(data);}JSONObject m=new JSONObject();m.put("title",title);m.put("notes",notes);m.put("date",new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",java.util.Locale.getDefault()).format(new java.util.Date()));m.put("fileName",safe);try(FileOutputStream o=new FileOutputStream(new File(d,safe+".json"))){o.write(m.toString().getBytes(StandardCharsets.UTF_8));}return "OK:"+safe;}catch(Exception e){return "Помилка збереження PDF: "+e.getMessage();}}@JavascriptInterface public String listPdfs(){JSONArray a=new JSONArray();File d=new File(folder("drawings"),"PDF");File[] fs=d.listFiles((dir,n)->n.toLowerCase().endsWith(".pdf"));if(fs==null)return a.toString();Arrays.sort(fs,(x,y)->Long.compare(y.lastModified(),x.lastModified()));for(File f:fs)try{JSONObject o=new JSONObject();File mf=new File(d,f.getName()+".json");if(mf.exists())o=new JSONObject(read(mf));o.put("fileName",f.getName());o.put("size",f.length());a.put(o);}catch(Exception ignored){}return a.toString();}@JavascriptInterface public String deletePdf(String name){try{String s=name.replaceAll("[^a-zA-Z0-9а-яА-ЯіІїЇєЄ._-]","_");if(!s.toLowerCase().endsWith(".pdf"))return "Некоректна назва PDF.";File d=new File(folder("drawings"),"PDF"),f=new File(d,s),m=new File(d,s+".json");if(f.exists()&&!f.delete())return "Не вдалося видалити PDF.";if(m.exists())m.delete();return "OK";}catch(Exception e){return "Помилка: "+e.getMessage();}}@JavascriptInterface public String saveImage(String c,String name,String data,String title,String notes,String date){try{int comma=data.indexOf(',');byte[] bytes=Base64.decode(comma>=0?data.substring(comma+1):data,Base64.DEFAULT);String safe=name.replaceAll("[^a-zA-Z0-9а-яА-ЯіІїЇєЄ._-]","_");File d=folder(c),f=new File(d,safe);try(FileOutputStream o=new FileOutputStream(f)){o.write(bytes);}JSONObject m=new JSONObject();m.put("title",title);m.put("notes",notes);m.put("date",date);m.put("fileName",safe);try(FileOutputStream o=new FileOutputStream(new File(d,safe+".json"))){o.write(m.toString().getBytes(StandardCharsets.UTF_8));}return "OK";}catch(Exception e){return "Помилка збереження: "+e.getMessage();}}@JavascriptInterface public String listImages(String c){JSONArray a=new JSONArray();File[] fs=folder(c).listFiles((d,n)->n.toLowerCase().endsWith(".jpg"));if(fs==null)return a.toString();Arrays.sort(fs,(x,y)->Long.compare(y.lastModified(),x.lastModified()));for(File f:fs)try{File mf=new File(f.getParentFile(),f.getName()+".json");JSONObject o=mf.exists()?new JSONObject(read(mf)):new JSONObject();o.put("fileName",f.getName());o.put("dataUrl","data:image/jpeg;base64,"+Base64.encodeToString(bytes(f),Base64.NO_WRAP));a.put(o);}catch(Exception ignored){}return a.toString();}@JavascriptInterface public String deleteImage(String c,String n){try{String s=n.replaceAll("[^a-zA-Z0-9а-яА-ЯіІїЇєЄ._-]","_");File d=folder(c),f=new File(d,s),m=new File(d,s+".json");if(f.exists()&&!f.delete())return "Не вдалося видалити";if(m.exists())m.delete();return "OK";}catch(Exception e){return "Помилка: "+e.getMessage();}}}private static byte[] bytes(File f)throws Exception{try(FileInputStream i=new FileInputStream(f);ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=i.read(b))>0)o.write(b,0,n);return o.toByteArray();}}private static String read(File f)throws Exception{return new String(bytes(f),StandardCharsets.UTF_8);}@Override public void onCreate(Bundle b){super.onCreate(b);WebView w=new WebView(this);w.setWebViewClient(new WebViewClient());w.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(callback!=null)callback.onReceiveValue(null);callback=cb;try{startActivityForResult(p.createIntent(),PICK);}catch(Exception e){callback=null;cb.onReceiveValue(null);return false;}return true;}});WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);w.addJavascriptInterface(new AndroidStorage(),"AndroidStorage");w.setBackgroundColor(0xFFF4F6F8);setContentView(w);activeWebView=w;folder("drawings");folder("products");w.loadUrl("file:///android_asset/index.html");}@Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==SAVE){String msg="Збереження скасовано.";try{if(c==RESULT_OK&&d!=null&&d.getData()!=null&&pendingExport!=null){try(OutputStream out=getContentResolver().openOutputStream(d.getData())){if(out==null)throw new IOException("Не вдалося відкрити файл");out.write(pendingExport);}msg="Файл збережено: "+pendingExportName;}}catch(Exception e){msg="Помилка збереження: "+e.getMessage();}pendingExport=null;final String message=msg;if(activeWebView!=null)activeWebView.post(()->activeWebView.evaluateJavascript("document.getElementById('excelExportStatus').textContent="+JSONObject.quote(message)+";",null));return;}if(r==PICK&&callback!=null){Uri[] u=null;if(c==RESULT_OK&&d!=null){if(d.getClipData()!=null){ClipData clip=d.getClipData();u=new Uri[clip.getItemCount()];for(int i=0;i<clip.getItemCount();i++)u[i]=clip.getItemAt(i).getUri();}else if(d.getData()!=null){u=new Uri[]{d.getData()};}}callback.onReceiveValue(u);callback=null;}}}
